def transform(grid):
    H, W = len(grid), len(grid[0])
    seen = [[False]*W for _ in range(H)]
    objs = []
    total = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and not seen[r][c]:
                stack = [(r, c)]; seen[r][c] = True; cells = []
                while stack:
                    y, x = stack.pop(); cells.append((y, x, grid[y][x]))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < H and 0 <= nx < W and not seen[ny][nx] and grid[ny][nx] != 0:
                            seen[ny][nx] = True; stack.append((ny, nx))
                objs.append(cells)
                total += len(cells)
    shift = total // 2 + 1
    out = [[0]*W for _ in range(H)]
    for cells in objs:
        r0 = min(y for y, _, _ in cells) - shift
        r1 = max(y for y, _, _ in cells) - shift
        c0 = min(x for _, x, _ in cells)
        c1 = max(x for _, x, _ in cells)
        for rr in range(r0-1, r1+2):
            for cc in range(c0-1, c1+2):
                if 0 <= cc < W:
                    out[rr % H][cc] = 6
        bot = (r1+1) % H
        for rr in range(bot, H):
            for cc in range(c0-1, c1+2):
                if 0 <= cc < W:
                    out[rr][cc] = 6
    for cells in objs:
        for y, x, v in cells:
            out[(y-shift) % H][x] = v
    return out
```

