def transform(grid):
    import numpy as np
    g = np.rot90(np.array(grid), 2)
    H, W = g.shape
    seen = np.zeros_like(g, dtype=bool)
    rects = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != 0 and not seen[r, c]:
                col = g[r, c]
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
