                        if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] == col:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                ys = [p[0] for p in cells]; xs = [p[1] for p in cells]
                rects.append((min(ys), max(ys), min(xs), max(xs), col))
    out = np.zeros_like(g)
    for r0, r1, c0, c1, col in rects:
